package si.spindl.reports;

import si.spindl.common.exception.BadRequestException;
import si.spindl.common.exception.ConflictException;
import si.spindl.common.exception.NotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import si.spindl.identity.TenantAuditEventEntity;
import si.spindl.identity.TenantAuditEventRepository;
import java.util.*;
import java.text.NumberFormat;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import si.spindl.reports.InvoiceTemplateDtos.TemplateConfig;
import si.spindl.reports.InvoiceTemplateDtos.TemplateVersion;
import si.spindl.reports.InvoiceTemplateDtos.TemplateView;
import si.spindl.reports.InvoiceTemplateDtos.PreviewField;
import si.spindl.reports.InvoiceTemplateDtos.Preview;
import si.spindl.reports.InvoiceTemplateDtos.Validation;

@Service
public class InvoiceTemplateService {
    public static final String TEMPLATE_KEY="invoice_document_template";
    private static final Set<String> ALLOWED_FIELDS=Set.of("invoiceNumber","issueDate","dueDate","customerName","customerEmail","subtotal","tax","total","amountPaid","balance");
    private final TenantWorkflowVersionRepository versions;private final TenantAuditEventRepository audit;
    public InvoiceTemplateService(TenantWorkflowVersionRepository versions,TenantAuditEventRepository audit){this.versions=versions;this.audit=audit;}
    @Transactional(readOnly=true) public TemplateView view(UUID tenantId){var all=versions.findAllByTenantIdAndWorkflowKeyOrderByVersionDesc(tenantId,TEMPLATE_KEY);var published=all.stream().filter(v->v.getStatus().equals("PUBLISHED")).findFirst().map(InvoiceTemplateMapper::toTemplateVersion).orElse(null);var draft=all.stream().filter(v->v.getStatus().equals("DRAFT")).findFirst().map(InvoiceTemplateMapper::toTemplateVersion).orElse(null);return new TemplateView(TEMPLATE_KEY,published,draft,all.stream().map(InvoiceTemplateMapper::toTemplateVersion).toList());}
    @Transactional public TemplateVersion createDraft(UUID tenantId,UUID actor,TemplateConfig config){if(versions.existsByTenantIdAndWorkflowKeyAndStatus(tenantId,TEMPLATE_KEY,"DRAFT"))throw conflict("Finish the current invoice template draft first");validate(config);var saved=versions.save(new TenantWorkflowVersionEntity(tenantId,TEMPLATE_KEY,versions.findMaxVersion(tenantId,TEMPLATE_KEY)+1,toMap(config),actor));audit.save(new TenantAuditEventEntity(tenantId,actor,"INVOICE_TEMPLATE_DRAFT_CREATED","document_template",saved.getId(),Map.of("version",saved.getVersion())));return InvoiceTemplateMapper.toTemplateVersion(saved);}
    @Transactional public TemplateVersion updateDraft(UUID tenantId,UUID actor,UUID id,TemplateConfig config){var entity=versions.findForUpdate(tenantId,id).filter(v->v.getWorkflowKey().equals(TEMPLATE_KEY)).orElseThrow(()->notFound());validate(config);entity.updateDraft(toMap(config));audit.save(new TenantAuditEventEntity(tenantId,actor,"INVOICE_TEMPLATE_DRAFT_UPDATED","document_template",id,Map.of("version",entity.getVersion())));return InvoiceTemplateMapper.toTemplateVersion(entity);}
    @Transactional(readOnly=true) public Preview preview(UUID tenantId,UUID id){var version=find(tenantId,id);TemplateConfig config=fromMap(version.getConfiguration());validate(config);Locale locale=Locale.forLanguageTag(config.locale());NumberFormat currency=NumberFormat.getCurrencyInstance(locale);DateTimeFormatter date=DateTimeFormatter.ofLocalizedDate(FormatStyle.MEDIUM).withLocale(locale);Map<String,String> sample=Map.of("invoiceNumber","INV-2026-000123","issueDate",date.format(LocalDate.of(2026,11,14)),"dueDate",date.format(LocalDate.of(2026,12,14)),"customerName","Northwind Manufacturing","customerEmail","accounts@example.com","subtotal",currency.format(12500),"tax",currency.format(2250),"total",currency.format(14750),"amountPaid",currency.format(5000),"balance",currency.format(9750));return new Preview(InvoiceTemplateMapper.toTemplateVersion(version),config.fields().stream().map(field->new PreviewField(field,label(field),sample.get(field))).toList());}
    @Transactional(readOnly=true) public Validation validate(UUID tenantId,UUID id){TemplateConfig config=fromMap(find(tenantId,id).getConfiguration());validate(config);Preview preview=preview(tenantId,id);return new Validation(true,List.of("Document type is supported.","Every displayed field is allowlisted.","Branding values contain no executable markup.","Invoice number and total are visible."),preview);}
    @Transactional public TemplateVersion publish(UUID tenantId,UUID actor,UUID id){var entity=versions.findForUpdate(tenantId,id).filter(v->v.getWorkflowKey().equals(TEMPLATE_KEY)).orElseThrow(()->notFound());validate(fromMap(entity.getConfiguration()));versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,TEMPLATE_KEY,"PUBLISHED").ifPresent(TenantWorkflowVersionEntity::rollback);entity.publish();audit.save(new TenantAuditEventEntity(tenantId,actor,"INVOICE_TEMPLATE_PUBLISHED","document_template",id,Map.of("version",entity.getVersion())));return InvoiceTemplateMapper.toTemplateVersion(entity);}
    @Transactional public TemplateView rollback(UUID tenantId,UUID actor){var current=versions.findFirstByTenantIdAndWorkflowKeyAndStatusOrderByVersionDesc(tenantId,TEMPLATE_KEY,"PUBLISHED").orElseThrow(()->conflict("There is no published invoice template"));var previous=versions.findAllByTenantIdAndWorkflowKeyOrderByVersionDesc(tenantId,TEMPLATE_KEY).stream().filter(v->v.getVersion()<current.getVersion()&&v.getStatus().equals("ROLLED_BACK")).findFirst().orElseThrow(()->conflict("There is no earlier invoice template to restore"));current.rollback();previous.republish();audit.save(new TenantAuditEventEntity(tenantId,actor,"INVOICE_TEMPLATE_ROLLED_BACK","document_template",previous.getId(),Map.of("fromVersion",current.getVersion(),"toVersion",previous.getVersion())));return view(tenantId);}
    private TenantWorkflowVersionEntity find(UUID tenantId,UUID id){return versions.findById(id).filter(v->v.getTenantId().equals(tenantId)&&v.getWorkflowKey().equals(TEMPLATE_KEY)).orElseThrow(this::notFound);}
    private void validate(TemplateConfig c){if(c==null)throw badRequest("Enter invoice template settings");if(c.documentType()==null||!c.documentType().equals("INVOICE"))throw badRequest("Only invoice templates are supported");if(c.title()==null||c.title().isBlank()||c.title().trim().length()>100||c.title().contains("<")||c.title().contains(">"))throw badRequest("Template title must contain 1 to 100 characters and cannot contain markup");if(c.footer()==null||c.footer().length()>240||c.footer().contains("<")||c.footer().contains(">"))throw badRequest("Footer text must be 240 characters or less and cannot contain markup");if(c.locale()==null||!Set.of("en-IN","en-US").contains(c.locale()))throw badRequest("Choose a supported invoice locale");if(c.accentColor()==null||!c.accentColor().matches("#[0-9A-Fa-f]{6}"))throw badRequest("Accent color must be a six-digit hex color");if(c.fields()==null||c.fields().size()<2||c.fields().size()>10||c.fields().stream().distinct().count()!=c.fields().size()||!ALLOWED_FIELDS.containsAll(c.fields()))throw badRequest("Choose 2 to 10 unique allowlisted invoice fields");if(!c.fields().contains("invoiceNumber")||!c.fields().contains("total"))throw badRequest("Invoice number and total must remain visible");}
    private Map<String,Object> toMap(TemplateConfig c){return Map.of("documentType",c.documentType(),"title",c.title().trim(),"footer",c.footer().trim(),"locale",c.locale(),"accentColor",c.accentColor().toUpperCase(Locale.ROOT),"fields",List.copyOf(c.fields()));}
    @SuppressWarnings("unchecked") private TemplateConfig fromMap(Map<String,Object> m){return new TemplateConfig(String.valueOf(m.get("documentType")),String.valueOf(m.get("title")),String.valueOf(m.get("footer")),String.valueOf(m.get("locale")),String.valueOf(m.get("accentColor")),((List<?>)m.get("fields")).stream().map(String::valueOf).toList());}
    private String label(String key){return Arrays.stream(key.replaceAll("([a-z])([A-Z])","$1 $2").split(" ")).map(s->s.substring(0,1).toUpperCase(Locale.ROOT)+s.substring(1)).collect(java.util.stream.Collectors.joining(" "));}
    private ResponseStatusException badRequest(String s){return new BadRequestException(s);}private ResponseStatusException conflict(String s){return new ConflictException(s);}private ResponseStatusException notFound(){return new NotFoundException("Invoice template version not found");}
}
